function resumerJournal(journal) {
  const bilan = {};
  for (const ligne of journal) {
    const [, etat, composant] = ligne.split(" ");
    if (!(composant in bilan)) {
      bilan[composant] = { erreurs: 0, dernier: etat };
    }
    if (etat === "ERR") {
      bilan[composant].erreurs += 1;
    }
    bilan[composant].dernier = etat;
  }
  return bilan;
}

