solution.javascript:
function trouverOrigines(journal, dependances) {
  const etat = {};
  const origine = {};
  const bilan = {};
  for (const ligne of journal) {
    const [, nouveau, composant] = ligne.split(" ");
    const avant = etat[composant];
    if (nouveau === "ERR" && avant !== "ERR") {
      let racine = composant;
      for (const dep of dependances[composant] || []) {
        if (etat[dep] === "ERR") {
          racine = origine[dep];
          break;
        }
      }
      origine[composant] = racine;
      bilan[racine] = (bilan[racine] || 0) + 1;
    }
    etat[composant] = nouveau;
  }
  return bilan;
}

