def trouver_origines(journal, dependances):
    etat = {}
    origine = {}
    bilan = {}
    for ligne in journal:
        _, nouveau, composant = ligne.split(" ")
        avant = etat.get(composant)
        if nouveau == "ERR" and avant != "ERR":
            racine = composant
            for dep in dependances.get(composant, []):
                if etat.get(dep) == "ERR":
                    racine = origine[dep]
                    break
            origine[composant] = racine
            bilan[racine] = bilan.get(racine, 0) + 1
        etat[composant] = nouveau
    return bilan

